CREATE FUNCTION public.guard_order_revision_history() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'Auftragsfassungen sind unveränderlich'; END; $$;
CREATE TRIGGER immutable_order_revision_history BEFORE UPDATE OR DELETE ON public.rental_order_revisions FOR EACH ROW EXECUTE FUNCTION public.guard_order_revision_history();
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.save_rental_order_amendment(uuid,integer,jsonb,text,timestamptz)'::regprocedure) INTO d;
d:=replace(d,'DECLARE r public.rental_inquiries; total numeric;', 'DECLARE r public.rental_inquiries; expected_total numeric; total numeric;');
d:=replace(d,'total:=(_payload', E'SELECT round(COALESCE(sum(round((i->>\'quantity\')::numeric*(i->>\'unit_price\')::numeric*(1-COALESCE((i->>\'discount_percent\')::numeric,0)/100),2)*(1+COALESCE((i->>\'vat_rate\')::numeric,19)/100)+COALESCE((SELECT sum((a->>\'amount\')::numeric)*1.19 FROM jsonb_array_elements(COALESCE(i->\'addons\',\'[]\'::jsonb)) a WHERE COALESCE((a->>\'optional\')::boolean,false)=false),0)),0),2) INTO expected_total FROM jsonb_array_elements(_payload->\'items\') i;\nexpected_total:=round(expected_total+1.19*(COALESCE((_payload->>\'delivery_cost_delivery\')::numeric,0)+COALESCE((_payload->>\'delivery_cost_return\')::numeric,0)+COALESCE((_payload->>\'setup_cost\')::numeric,0)+COALESCE((_payload->>\'dismantle_cost\')::numeric,0)+COALESCE((_payload->>\'return_location_cost\')::numeric,0)),2);\nIF abs(expected_total-(_payload->\'totals\'->>\'grossAmount\')::numeric)>0.02 THEN RAISE EXCEPTION \'Auftragssumme stimmt nicht mit Positionen überein\'; END IF;\ntotal:=(_payload');
d:=replace(d,'availability_pending=true WHERE id=_id;', E'availability_pending=true,start_date=(SELECT min(i->>\'rental_start\')::date FROM jsonb_array_elements(_payload->\'items\') i),end_date=(SELECT max(i->>\'rental_end\')::date FROM jsonb_array_elements(_payload->\'items\') i) WHERE id=_id;');
d:=replace(d,'availability:=public.check_availability(_id);', E'PERFORM id FROM public.b2b_managed_products WHERE slug IN(SELECT i->>\'product_slug\' FROM jsonb_array_elements(_payload->\'items\') i) ORDER BY id FOR UPDATE;\navailability:=public.check_availability(_id);');
EXECUTE d;
END $$;